public List<Integer> grayCode(int n) {
    List<Integer> result = new ArrayList<>();
    result.add(0);
    for (int k = 0; k < n; k++) {
        int highBit = 1 << k;
        for (int i = result.size() - 1; i >= 0; i--) {
            result.add(result.get(i) | highBit); // reflect + set new bit
        }
    }
    return result;
}

